/* Chinar service worker — generated by scripts/build.mjs. Do not edit dist/sw.js. */
const VERSION = '__BUILD_ID__';
const SHELL = `chinar-shell-${VERSION}`;
const RUNTIME = `chinar-runtime-${VERSION}`;
const PRECACHE = __PRECACHE__;
const OFFLINE_URL = '__OFFLINE_URL__';

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(SHELL)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting())
      .catch((error) => console.warn('[sw] precache incomplete', error))
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(
        keys.filter((k) => k !== SHELL && k !== RUNTIME).map((k) => caches.delete(k))
      ))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
});

const isAsset = (url) => /\.(css|js|svg|png|webp|avif|woff2?)$/.test(url.pathname);

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Documents: network first, fall back to cache, then to the offline page.
  if (request.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const fresh = await fetch(request);
        const cache = await caches.open(RUNTIME);
        cache.put(request, fresh.clone());
        return fresh;
      } catch {
        return (await caches.match(request))
          || (await caches.match(OFFLINE_URL))
          || new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } });
      }
    })());
    return;
  }

  // Static assets: cache first, refreshed in the background.
  if (isAsset(url)) {
    event.respondWith((async () => {
      const cached = await caches.match(request);
      const network = fetch(request)
        .then(async (response) => {
          if (response.ok) {
            const cache = await caches.open(SHELL);
            cache.put(request, response.clone());
          }
          return response;
        })
        .catch(() => cached);
      return cached || network;
    })());
  }
});
